def file_name_check(file_name):
    if file_name.count('.') != 1:
        return 'No'

    name_part, extension = file_name.split('.')

    if extension not in ['txt', 'exe', 'dll']:
        return 'No'

    if not name_part or not (('a' <= name_part[0] <= 'z') or ('A' <= name_part[0] <= 'Z')):
        return 'No'

    if sum(1 for c in file_name if '0' <= c <= '9') > 3:
        return 'No'

    return 'Yes'
